<template><div class="answer-feedback" aria-label="回答反馈"><button :disabled="busy" :aria-pressed="rating==='helpful'" @click="submit(rating==='helpful'?'':'helpful')">{{ rating==='helpful'?'✓ 有帮助':'有帮助' }}</button><button :disabled="busy" :aria-pressed="rating==='problem'" @click="open=true">有问题</button><span role="status">{{ status }}</span><form v-if="open" @submit.prevent="submit('problem')"><label>问题类型<select v-model="reason"><option value="irrelevant">答非所问</option><option value="incorrect">事实或推理错误</option><option value="citation">引用有误</option><option value="incomplete">回答不完整</option><option value="other">其他</option></select></label><textarea v-model="comment" maxlength="500" rows="2" placeholder="可以补充原因（选填，最多500字）"/><button :disabled="busy">提交反馈</button><button type="button" @click="open=false">取消</button></form></div></template>
<script setup lang="ts">
import {ref,watch} from 'vue';import request from '@/utils/request'
const props=defineProps<{runId:string}>(),rating=ref(''),reason=ref('incorrect'),comment=ref(''),busy=ref(false),open=ref(false),status=ref('');let generation=0
watch(()=>props.runId,async id=>{const turn=++generation;rating.value='';try{const r:any=await request.get(`/agent/runs/${id}/feedback`);if(turn===generation && r.data){rating.value=r.data.rating;reason.value=r.data.reason||'incorrect';comment.value=r.data.comment||''}}catch{}},{immediate:true})
async function submit(value:string){if(busy.value)return;const id=props.runId,turn=generation;busy.value=true;status.value='';try{await request.put(`/agent/runs/${id}/feedback`,{rating:value,reason:reason.value,comment:comment.value});if(turn===generation){rating.value=value;open.value=false;status.value=value?'感谢反馈，已记录':'已撤销反馈'}}catch(e){if(turn===generation)status.value=e instanceof Error?e.message:'提交失败，请重试'}finally{busy.value=false}}
</script>
<style scoped>.answer-feedback{margin-top:12px;font-size:12px;color:var(--ej-muted);display:flex;gap:8px;flex-wrap:wrap}.answer-feedback button{border:1px solid var(--ej-line);border-radius:99px;padding:5px 12px;background:var(--ej-surface);cursor:pointer}.answer-feedback button[aria-pressed=true]{background:var(--studio-lime)}.answer-feedback form{flex-basis:100%;display:flex;gap:8px;flex-wrap:wrap;padding:12px;border:1px solid var(--ej-line);border-radius:14px}.answer-feedback textarea{flex-basis:100%;width:100%;background:var(--ej-surface);border:1px solid var(--ej-line);border-radius:8px;padding:8px}.answer-feedback select{margin-left:8px}</style>
